// Helper functions
type movieTrailerLink struct {
	Name string
	Type string
	URL  string
}

func movieTrailerLinks(videos []models.RelatedVideo) []movieTrailerLink {
	trailers := make([]movieTrailerLink, 0, 3)
	for _, video := range videos {
		if !strings.EqualFold(video.Site, "YouTube") || !strings.EqualFold(video.Type, "Trailer") {
			continue
		}

		validKey := video.Key != ""
		for _, char := range video.Key {
			if !(char >= 'a' && char <= 'z' || char >= 'A' && char <= 'Z' || char >= '0' && char <= '9' || char == '-' || char == '_') {
				validKey = false
				break
			}
		}
		if !validKey {
			continue
		}

		name := strings.TrimSpace(video.Name)
		if name == "" {
			name = "Official Trailer"
		}
		trailers = append(trailers, movieTrailerLink{
			Name: name,
			Type: video.Type,
			URL:  "https://www.youtube.com/watch?v=" + video.Key,
		})
		if len(trailers) == 3 {
			break
		}
	}
	return trailers
}

func safeRatingURL(raw string) templ.SafeURL {
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Hostname() == "" || parsed.User != nil {
		return templ.SafeURL("")
	}
	if strings.EqualFold(parsed.Scheme, "http") && parsed.Port() == "" {
		host := strings.ToLower(parsed.Hostname())
		if host == "rottentomatoes.com" || host == "www.rottentomatoes.com" {
			parsed.Scheme = "https"
		}
	}
	if !strings.EqualFold(parsed.Scheme, "https") {
		return templ.SafeURL("")
	}
	return templ.URL(parsed.String())
}

func movieIMDbURL(imdbID string) templ.SafeURL {
	if imdbID == "" {
		return ""
	}
	return safeRatingURL("https://www.imdb.com/title/" + imdbID)
}

func hasMovieFacts(movie models.MovieDetails) bool {
	return movie.Movie.ReleaseDate != nil || movie.Runtime > 0 || movie.Movie.OriginalLanguage != "" ||
		movie.Status != "" || len(movie.ProductionCompanies) > 0 ||
		len(movie.ProductionCountries) > 0 || movie.Budget > 0 || movie.Revenue > 0
}

func productionCompanyNames(companies []models.ProductionCompany) string {
	names := make([]string, 0, len(companies))
	for _, company := range companies {
		if name := strings.TrimSpace(company.Name); name != "" {
			names = append(names, name)
		}
	}
	return strings.Join(names, ", ")
}

func productionCountryNames(countries []models.ProductionCountry) string {
	names := make([]string, 0, len(countries))
	for _, country := range countries {
		name := strings.TrimSpace(country.Name)
		if name == "" {
			name = country.ISOCode
		}
		if name != "" {
			names = append(names, name)
		}
	}
	return strings.Join(names, ", ")
}

func ratingSourceAsset(source string, value float64) (string, string, string) {
	switch source {
	case "TMDB":
		return "/static/images/ratings/tmdb.svg", "TMDB", "h-[22px]"
	case "IMDb":
		return "/static/images/ratings/imdb.svg", "IMDb", "h-6"
	case "RT Critics":
		if value >= rottenTomatoesPositiveScoreThreshold {
			return "/static/images/ratings/tomatometer-fresh.svg", "Fresh tomato", "h-[26px]"
		}
		return "/static/images/ratings/tomatometer-rotten.svg", "Rotten splat", "h-[26px]"
	case "RT Audience":
		if value >= rottenTomatoesPositiveScoreThreshold {
			return "/static/images/ratings/popcornmeter-hot.svg", "Hot popcorn", "h-[26px]"
		}
		return "/static/images/ratings/popcornmeter-stale.svg", "Stale popcorn", "h-[30px]"
	default:
		return "", "", ""
	}
}

func formatMoney(amount int64) string {
	if amount == 0 {
		return "N/A"
	}
	switch {
	case amount >= 1000000000:
		return fmt.Sprintf("$%.1fB", float64(amount)/1000000000)
	case amount >= 1000000:
		return fmt.Sprintf("$%.1fM", float64(amount)/1000000)
	case amount >= 1000:
		return fmt.Sprintf("$%.1fK", float64(amount)/1000)
	default:
		return "$" + strconv.FormatInt(amount, 10)
	}
}

func formatNumber(num int64) string {
	str := strconv.FormatInt(num, 10)
	n := len(str)
	if n <= 3 {
		return str
	}

	var result strings.Builder
	for i, digit := range str {
		if i > 0 && (n-i)%3 == 0 {
			result.WriteString(",")
		}
		result.WriteRune(digit)
	}
	return result.String()
}

func countTheaterWatches(records []models.WatchedMovieRecord) int {
	count := 0
	for _, record := range records {
		if record.InTheaters {
			count++
		}
	}
	return count
}

func calculateAverageRating(records []models.WatchedMovieRecord) string {
	var sum float64
	var count int
	for _, record := range records {
		if record.Rating != nil {
			sum += *record.Rating
			count++
		}
	}
	if count == 0 {
		return "N/A"
	}
	return fmt.Sprintf("%.1f/5", sum/float64(count))
}

func sortCast(cast []models.Cast) []models.Cast {
	slices.SortFunc(cast, func(a, b models.Cast) int {
		return cmp.Compare(a.CastOrder, b.CastOrder)
	})
	return cast
}

func formatTimeAgo(t time.Time) string {
	now := time.Now()
	diff := now.Sub(t)

	switch {
	case diff < time.Hour:
		if minutes := int(diff.Minutes()); minutes < 1 {
			return "Just now"
		} else {
			return fmt.Sprintf("%dm ago", minutes)
		}
	case diff < 24*time.Hour:
		return fmt.Sprintf("%dh ago", int(diff.Hours()))
	case diff < 30*24*time.Hour:
		return fmt.Sprintf("%dd ago", int(diff.Hours()/24))
	case diff < 365*24*time.Hour:
		return fmt.Sprintf("%dmo ago", int(diff.Hours()/(24*30)))
	default:
		return fmt.Sprintf("%dy ago", int(diff.Hours()/(24*365)))
	}
}

func sortCrewByImportance(crew []models.Crew) []models.Crew {
	importanceOrder := map[string]int{
		"Director":                1,
		"Director of Photography": 2,
		"Cinematography":          2,
		"Screenplay":              3,
		"Writer":                  3,
		"Music":                   4,
		"Producer":                5,
		"Executive Producer":      6,
		"Editor":                  7,
		"Production Designer":     8,
	}

	var keyCrew []models.Crew
	for _, member := range crew {
		if _, ok := importanceOrder[member.Job]; ok {
			keyCrew = append(keyCrew, member)
		}
	}

	slices.SortFunc(keyCrew, func(a, b models.Crew) int {
		return cmp.Compare(importanceOrder[a.Job], importanceOrder[b.Job])
	})

	return keyCrew
}

func getDirector(crew []models.Crew) models.Crew {
	for _, member := range crew {
		if member.Job == "Director" {
			return member
		}
	}
	return models.Crew{}
}

